body:
{
  "name": "RevenueCat",
  "version": "5.95.0",
  "summary": "Subscription and in-app-purchase backend service.",
  "description": "Save yourself the hassle of implementing a subscriptions backend. Use RevenueCat instead https://www.revenuecat.com/",
  "homepage": "https://www.revenuecat.com/",
  "license": {
    "type": "MIT"
  },
  "authors": {
    "RevenueCat, Inc.": "support@revenuecat.com"
  },
  "source": {
    "git": "https://github.com/revenuecat/purchases-ios.git",
    "tag": "5.95.0"
  },
  "documentation_url": "https://docs.revenuecat.com/",
  "frameworks": "StoreKit",
  "swift_versions": "5.8",
  "platforms": {
    "ios": "13.0",
    "watchos": "6.2",
    "tvos": "13.0",
    "osx": "10.15",
    "visionos": "1.0"
  },
  "pod_target_xcconfig": {
    "DEFINES_MODULE": "YES",
    "SWIFT_ACTIVE_COMPILATION_CONDITIONS": "$(inherited) COCOAPODS",
    "SWIFT_ACTIVE_COMPILATION_CONDITIONS[sdk=xros*]": "$(inherited) COCOAPODS VISION_OS",
    "SWIFT_ACTIVE_COMPILATION_CONDITIONS[sdk=xrsimulator*]": "$(inherited) COCOAPODS VISION_OS"
  },
  "source_files": "Sources/**/*.swift",
  "exclude_files": "Sources/LocalReceiptParsing/ReceiptParser-only-files/**",
  "resource_bundles": {
    "RevenueCat": [
      "Sources/PrivacyInfo.xcprivacy"
    ]
  },
  "swift_version": "5.8"
}
